myth = diss(p(title="Impact of Chinese Mythology-Based Animated Characters on Audience Aesthetic Preferences", titleZh="中国神话动画人物对受众审美偏好的影响", authors="Han Fang, WonJun Chung", year=2026, venue="Journal of the Korean Institute of Design Research, 11(2), 931–944", source="KCI", category="博士论文专题 · 中国神话人物", url="https://doi.org/10.46248/kidrs.2026.2.931", doi="https://doi.org/10.46248/kidrs.2026.2.931", topicIds=["culture", "methods"], publicationType="journal", publicationStatus="published", publicationDate="2026", publicationDatePrecision="year", takeaway="对416名受众的结构方程分析显示，现代技术、符号融合和现代价值构成通向审美偏好的顺序机制。技术首先提升愉悦，符号融合同时提升愉悦与兴趣，现代价值更集中地提升深层兴趣。", theory="结合刺激、机体、反应框架与愉悦、兴趣、审美模型，解释神话人物的形式和价值如何转化为偏好。", data="416名受众。", method="问卷与结构方程模型，比较现代技术、符号融合、现代价值、愉悦、兴趣和审美偏好的路径。", results="三类人物设计线索经不同的愉悦和兴趣路径关联审美偏好。", limitations="公开证据未显示跨国分层、随机操纵或Schwartz价值测量，横断面路径不能确立因果。", readingUse="用于中国神话人物、愉悦与兴趣的直接模型。", researchConnection="这是本期与中国神话人物接收最直接的同行评审证据，但审美偏好不能替代理解、人物认同或传播意向。"), "Fang, H., & Chung, W. (2026). Impact of Chinese mythology-based animated characters on audience aesthetic preferences. Journal of the Korean Institute of Design Research, 11(2), 931–944. https://doi.org/10.46248/kidrs.2026.2.931", "人物设计中的现代价值和符号融合分别经兴趣与愉悦影响审美偏好，但这些路径不等于人物认同。", "以同一中国神话人物交叉操纵符号融合强弱与价值线索，同时保持视觉质量和情节结果恒定。", "分别测量理解、愉悦、兴趣、审美偏好、人物认同和传播意向，并做区分效度检验。", "唯一直接研究中国神话动画人物且有416人结构模型，是本期首要精读。")

wukong = diss(p(title="Black Myth: Wukong in Heteroglossia: Video Adaptations as Articulations and Remediated ‘Fan Journalism’", titleZh="异质话语中的黑神话悟空：视频改编作为表达与再媒介化粉丝新闻", authors="Zixuan Zhu, Yihang Yan, Danqi Lu", year=2026, venue="Emerging Media, 4(1), 12–33", source="Emerging Media", category="博士论文专题 · 跨国粉丝接收", url="https://doi.org/10.1177/27523543261425261", doi="https://doi.org/10.1177/27523543261425261", topicIds=["culture"], publicationType="journal", publicationStatus="published", publicationDate="2026", publicationDatePrecision="year", takeaway="数字民族志比较中国与国际平台上各十位高观看量创作者的视频、评论和弹幕。悟空既被表达为民族象征，也被重构为个人能动性和粉丝共同身份；跨国参与还形成替代性团结，同时云游戏带来包容与分层。", theory="以异质话语、再媒介化和表达理论解释粉丝视频如何共同生产人物意义。", data="中国平台和国际平台各十位高观看量创作者及其视频、评论、弹幕与社区参与资料。", method="2024年6月起社区观察，重点资料覆盖2025年3月至6月的数字民族志与跨平台文本分析。", results="悟空意义在民族象征、个人能动性、共同身份和跨国团结之间被协商。", limitations="目的性选择高观看量创作者，不能估计总体受众比例，也不能识别类比表达的因果效果。", readingUse="用于跨国粉丝意义生产和自然语言反应编码。", researchConnection="该研究说明外国受众对人物的接收并非单一中国态度，而是对人物、社群和国家框架的多层协商。"), "Zhu, Z., Yan, Y., & Lu, D. (2026). Black Myth: Wukong in heteroglossia: Video adaptations as articulations and remediated fan journalism. Emerging Media, 4(1), 12–33. https://doi.org/10.1177/27523543261425261", "文化内外群体会赋予同一人物不同的民族、个人与社群意义，进而改变价值契合对认同的作用。", "在同一人物材料后随机呈现内群体、外群体或跨国粉丝的解释框架，并保留自然反应题。", "区分人物意义、民族象征、粉丝身份、个人能动性、人物认同和国家态度。", "直接覆盖中外平台的悟空粉丝接收，适合补足自然语境，但不作为因果设计依据。")

webtoon = diss(p(title="Fan identification and narrative transportation as determinants of perceived value of webtoon-based merchandise", titleZh="粉丝认同与叙事传输如何决定网漫衍生商品的感知价值", authors="Seungyeon Ha, Seongcheol Kim", year=2026, venue="Humanities and Social Sciences Communications, 13, 669", source="Humanities and Social Sciences Communications", category="博士论文专题 · 人物与粉丝认同", url="https://doi.org/10.1057/s41599-026-06961-2", doi="https://doi.org/10.1057/s41599-026-06961-2", topicIds=["culture", "methods"], publicationType="journal", publicationStatus="published", publicationDate="2026", publicationDatePrecision="year", takeaway="韩国网漫消费者调查得到293份有效样本。人物认同、设定丰富度和社会互动能力均预测粉丝认同与叙事传输；粉丝认同正向关联衍生商品价值，而叙事传输与商品价值无显著关系。", theory="区分内容层面的人物与世界设定、粉丝身份和叙事传输，并比较其对行为价值的不同路径。", data="韩国在线面板300人，排除无效回答后293人，2024年3月12日至14日收集。", method="七点量表问卷和偏最小二乘结构方程模型。", results="人物认同、设定丰富度和社会互动能力均关联两类中介；只有粉丝认同关联商品价值。", limitations="横断面自报不能确立因果，商品价值不等于分享意向，韩国网漫语境与外国受众接收中国神话不同。", readingUse="用于区分人物认同、粉丝认同、传输和行为价值。", researchConnection="该研究直接说明叙事投入不必然转化为行为价值，支持分开测量人物认同与传播意向。"), "Ha, S., & Kim, S. (2026). Fan identification and narrative transportation as determinants of perceived value of webtoon-based merchandise. Humanities and Social Sciences Communications, 13, 669. https://doi.org/10.1057/s41599-026-06961-2", "人物认同可经粉丝身份影响传播或消费价值，而叙事传输可能不产生相同结果。", "在相同叙事强度下操纵价值契合，并将粉丝身份作为中介或分层变量。", "分别测量人物认同、粉丝认同、叙事传输、商品价值和分享意向。", "变量区分和行为结果最贴近论文模型，列为重点阅读。")

values = diss(p(title="Perceived Value Congruence Between Parents: Effects on Young People’s Anxiety, Clear Communication, and Value Priorities", titleZh="父母之间的感知价值契合：对青年焦虑、清晰沟通与价值优先序的影响", authors="Hamdullah Tunç, Paul H. P. Hanel, Paul Graham Morris, Melina Nicole Kyranides, Joanne M. Williams", year=2026, venue="Current Psychology, 45, 902", source="Current Psychology", category="博士论文专题 · Schwartz价值契合", url="https://doi.org/10.1007/s12144-026-09393-y", doi="https://doi.org/10.1007/s12144-026-09393-y", topicIds=["culture", "methods"], publicationType="journal", publicationStatus="published", publicationDate="2026-05-04", publicationDatePrecision="day", takeaway="198名16至25岁青年报告父母价值及自身结果。响应面分析显示，父母在自我超越和自我增强上的相似性与较低焦虑相关，开放和自我增强相似性与更清晰沟通相关；父母共同高度重视某价值时，青年也更重视该价值。", theory="以Schwartz价值维度和响应面分析区分相似性、共同高水平与不一致方向。", data="198名青年，平均18.16岁，范围16至25岁。", method="自报问卷、二次多项式回归和响应面分析。", results="不同价值维度的契合关联不同结果，共同高水平还关联青年自身价值优先序。", limitations="横断面自报且对象为家庭关系，不能直接外推人物接收或确立方向因果。", readingUse="用于价值契合的响应面建模。", researchConnection="它避免把价值契合简化为差值分数，并直接采用Schwartz价值结构，是博士论文方法核心。"), "Tunç, H., Hanel, P. H. P., Morris, P. G., Kyranides, M. N., & Williams, J. M. (2026). Perceived value congruence between parents: Effects on young people’s anxiety, clear communication, and value priorities. Current Psychology, 45, 902. https://doi.org/10.1007/s12144-026-09393-y", "受众与人物在不同Schwartz高阶价值上的契合具有不同结果，且共同高价值与简单差异分数不同。", "先测受众价值，再用人物行为分别操纵自我超越、开放、保守和自我增强，采用响应面而非绝对差值。", "使用PVQ测受众价值和人物价值知觉，报告多项式项、响应面参数和测量等值性。", "直接采用Schwartz维度和响应面分析，是本期第二篇精读。")

indigenous = diss(p(title="The influence of indigenous documentary narratives on cultural resilience and mental health awareness", titleZh="原住民纪录片叙事对文化韧性与心理健康意识的影响", authors="P. Li, C. Jia, Y. Chen", year=2026, venue="Frontiers in Psychology, 17, 1975220", source="Frontiers in Psychology", category="博士论文专题 · 文化认同机制", url="https://doi.org/10.3389/fpsyg.2026.1975220", doi="https://doi.org/10.3389/fpsyg.2026.1975220", topicIds=["culture", "methods"], publicationType="journal", publicationStatus="published", publicationDate="2026-10-14", publicationDatePrecision="day", evidence="全文核验", takeaway="480名云南和湖南少数民族成年人观看四部彝、苗、白及土家苗题材纪录片，另有36人参加质性环节。叙事投入与文化韧性、心理健康意识正相关，与污名负相关；文化认同与真实性构成统计间接关联。", theory="以叙事投入、文化认同和感知真实性解释文化叙事的社会心理结果。", data="480名少数民族成年人和36名质性参与者。", method="标准化观看后的横断面混合方法、回归与间接效应分析。", results="叙事投入与韧性r=.51、意识r=.44、污名r=-.35；文化认同间接效应β=.225，真实性β=.114。", limitations="横断面自报和单次观看不能确立因果，样本是文化内部群体，不是外国受众。", readingUse="用于叙事投入、文化认同与真实性机制。", researchConnection="文化认同和真实性应与人物价值契合分开测量，并可作为内外群体边界机制。"), "Li, P., Jia, C., & Chen, Y. (2026). The influence of indigenous documentary narratives on cultural resilience and mental health awareness. Frontiers in Psychology, 17, 1975220. https://doi.org/10.3389/fpsyg.2026.1975220", "叙事投入与结果的关系可由文化认同和真实性分别承载，且不等同人物价值契合。", "交叉操纵人物价值框架与文化来源标签，并保持影像质量、叙事长度和事实信息一致。", "分别测量叙事投入、文化认同、感知真实性、人物价值契合、理解和传播意向。", "全文证据充分，适合校准文化认同与真实性的独立中介。")

proximity = diss(p(title="How proximity and trust of policy narrators motivate their audience", titleZh="政策叙述者的接近性与信任如何激励受众", authors="Elizabeth A. Shanahan, Rob A. DeLeo, Deserai Anderson, Kristin Taylor, Thomas A. Birkland, Clifton M. Chow, Danielle Blanch-Hartigan, Honey Minkowitz, Elizabeth A. Koebele", year=2026, venue="Journal of Public Policy, 46(1), 170–186", source="Journal of Public Policy", category="博士论文专题 · 类比来源与接近性", url="https://doi.org/10.1017/S0143814X25100937", doi="https://doi.org/10.1017/S0143814X25100937", topicIds=["culture", "methods"], publicationType="journal", publicationStatus="published", publicationDate="2026-01-08", publicationDatePrecision="day", takeaway="2268人的探索性实验把疫苗视觉信息的叙述者标为朋友、医生、美国疾控中心或某人。叙述者标签本身没有显著主效应，但接近叙述者与接近人物组合会影响接种动机；对远端叙述者的信任更关联情感，对近端叙述者的信任更关联动机。", theory="区分叙述者接近性、故事人物接近性与来源信任，并检验二者组合。", data="2268名参与者。", method="在疫苗视觉叙事后随机附加四类叙述者标签的探索性实验。", results="叙述者单独主效应不显著，接近叙述者与接近人物组合影响动机；信任路径随接近性不同。", limitations="疫苗政策与神话人物类比差异大，探索性分析需要预注册复现。", readingUse="用于本国类比的来源与人物双重接近性。", researchConnection="本国相似神话人物的效果可能来自解释者接近性、故事人物接近性或来源信任，三者必须拆开。"), "Shanahan, E. A., DeLeo, R. A., Anderson, D., Taylor, K., Birkland, T. A., Chow, C. M., Blanch-Hartigan, D., Minkowitz, H., & Koebele, E. A. (2026). How proximity and trust of policy narrators motivate their audience. Journal of Public Policy, 46(1), 170–186. https://doi.org/10.1017/S0143814X25100937", "本国类比只有在叙述者与人物接近性组合时才可能提高传播意向，来源信任是独立机制。", "采用2乘2设计分别操纵解释者来自本国或中国、类比人物来自本国或中国，并保持论证内容恒定。", "测量叙述者信任、人物接近性、文化熟悉性、加工流畅性、理解、好感、认同和传播意向。", "直接提供接近性与信任的组合操纵，是本期第三篇精读。")

